describe("issue.unassigned", () => {
  it("names the previous assignee and the actor who cleared it", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Drop me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const seen = capture("issue.unassigned");
    const updated = capture("issue.updated");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(updated).toHaveLength(0);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.admin,
      actorId: tenant.userIds.member,
    });
  });

  it("stays silent when clearing an issue that has no assignee", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Nobody holds me" }),
    );

    const seen = capture("issue.unassigned");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(seen).toHaveLength(0);
  });

  it("fires once per live issue when the assignee is removed from the org", async () => {
    const removal = await createTenant("unassign-on-remove", "growth");
    const target = await memberRepo.findMember(removal.org.id, removal.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const live = await issueService.createIssue(
      removal.actors.member,
      issueInput(removal.org.id, removal.project.id, {
        title: "Still open",
        assigneeId: removal.userIds.viewer,
      }),
    );
    const archived = await issueService.createIssue(
      removal.actors.member,
      issueInput(removal.org.id, removal.project.id, {
        title: "Already closed",
        assigneeId: removal.userIds.viewer,
      }),
    );
    await issueService.archiveIssue(removal.actors.member, removal.org.id, archived.id);

    const seen: TaskflowEventMap["issue.unassigned"][] = [];
    detachers.push(
      subscribe("issue.unassigned", (payload) => {
        if (payload.orgId === removal.org.id) seen.push(payload);
      }),
    );

    await memberService.removeMember(removal.actors.owner, {
      orgId: removal.org.id,
      memberId: target.id,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      issueId: live.id,
      projectId: removal.project.id,
      previousAssigneeId: removal.userIds.viewer,
      actorId: removal.userIds.owner,
    });
  });
});

